SourceCode.Declaration:
/// <summary>
/// Stock count control center: Keep this count - the supervisor's decision on the selected duplicate.
/// </summary>
class HSMobileOpsCountKeepLine
{
}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsCountStageLine line = _args ? _args.record() : null;

    if (!line || !line.RecId)
    {
        throw error('Select a counted line first.');
    }
    HSMobileOpsCountControl::decide(line, HSMobileOpsCountDuplicateDecision::KeepThis);
    if (_args && _args.caller() is FormRun)
    {
        FormRun callerForm = _args.caller() as FormRun;
        int     i;
        for (i = 1; i <= callerForm.dataSourceCount(); i++)
        {
            callerForm.dataSource(i).research(true);
        }
    }
}
